// Функция для изменения значения переменной KT_Tech_BTI
function updateKT_Tech_BTI(ktVarName, questionNumberVarName, valueVarName) {
    // Получаем объект Player
    var player = GetPlayer();
    
    // Получаем значение переменной KT_Tech_BTI, Question_Number_3 и значение переменной для записи
    var ktTechBTI = player.GetVar(ktVarName);
    var questionNumber = player.GetVar(questionNumberVarName);
    var newValue = player.GetVar(valueVarName);
    
    // Убираем каждый третий символ из newValue
    newValue = newValue.split('').filter(function(_, index) {
        return (index + 1) % 3 !== 0;
    }).join('');
    
    // Проверяем, получено ли корректное значение переменной KT_Tech_BTI
    if (ktTechBTI && typeof ktTechBTI === 'string') {
        // Преобразуем строку в массив
        var ktArray = ktTechBTI.slice(1, -1).split('],[').map(function(item) {
            return item ? item.split(',') : [];
        });
        
        // Определяем индекс для работы
        var index = questionNumber - 1;
        
        // Проверяем, существует ли указанный индекс в массиве
        if (index >= 0 && index < ktArray.length) {
            // Устанавливаем новое значение в указанной ячейке
            ktArray[index] = [newValue];
            
            // Преобразуем массив обратно в строку
            var updatedKtTechBTI = '[' + ktArray.map(function(item) {
                return item.join(',');
            }).join('],[') + ']';
            
            // Устанавливаем обновленное значение переменной KT_Tech_BTI
            player.SetVar(ktVarName, updatedKtTechBTI);
        }
    } else {
        console.error('Переменная KT_Tech_BTI не получена или имеет неверный формат.');
    }
}

// Пример вызова функции
var player = GetPlayer();
updateKT_Tech_BTI('KT_Tech_BTI', 'Question_Number_3', 'test_task_4_store');

// Функция для получения значений переменных из Articulate Storyline
function getVariable(player, varName) {
    return player.GetVar(varName);
}

// Функция для установки значения переменной в Articulate Storyline
function setVariable(player, varName, value) {
    player.SetVar(varName, value);
}

// Основной скрипт для поиска следующего слайда
function findNextSlideTrigger() {
    var player = GetPlayer();

    // Получение значений переменных от 3_1 до 3_12
    var variables = [];
    for (var i = 1; i <= 12; i++) {
        variables.push(getVariable(player, '3_' + i));
    }

    // Поиск точки отсчёта (переменная со значением 1)
    var startPoint = -1;
    for (var i = 0; i < variables.length; i++) {
        if (variables[i] === 1) {
            startPoint = i;
            break;
        }
    }

    if (startPoint === -1) {
        console.error('Точка отсчёта не найдена');
        return;
    }

    // Поиск переменной со значением 0 после точки отсчёта
    var nextSlideTrigger = 'Final';
    for (var i = startPoint + 1; i < variables.length; i++) {
        if (variables[i] === 0) {
            nextSlideTrigger = '3_' + (i + 1);
            break;
        }
    }

    // Если не найдено, поиск переменной со значением 0 до точки отсчёта
    if (nextSlideTrigger === 'Final') {
        for (var i = 0; i < startPoint; i++) {
            if (variables[i] === 0) {
                nextSlideTrigger = '3_' + (i + 1);
                break;
            }
        }
    }

    // Установка значения переменной Next_Slide_Trigger
    setVariable(player, 'Next_Slide_Trigger', nextSlideTrigger);
}

// Функция для добавления значения в список, если его там ещё нет
function updateQuestionList() {
    var player = GetPlayer();

    // Получение значения переменной Question_Number_3
    var questionNumber = getVariable(player, "Question_Number_3");

    // Инициализация списка, если он ещё не инициализирован
    var questionList = getVariable(player, "QuestionList_3") || [];

    // Проверка, является ли QuestionList строкой (если Storyline сохраняет его как строку)
    if (typeof questionList === 'string') {
        try {
            questionList = JSON.parse(questionList);
        } catch (e) {
            questionList = [];
        }
    }

    // Проверка, есть ли значение в списке
    if (!questionList.includes(questionNumber)) {
        // Добавление значения в список
        questionList.push(questionNumber);

        // Сохранение обновленного списка в переменную Storyline
        setVariable(player, "QuestionList_3", JSON.stringify(questionList));
    }
}

// Запуск функций
findNextSlideTrigger();
updateQuestionList();

// Инициализация глобальных переменных на уровне окна браузера
window.timerRunning = window.timerRunning || false;
window.timerInterval = window.timerInterval || null;
window.timerSeconds = window.timerSeconds || null;
window.lastUpdateTime = window.lastUpdateTime || null;

// Функция для запуска таймера
function startTimer() {
  // Останавливаем предыдущий таймер, если он существует
  stopTimer();

  // Получаем начальное значение таймера и преобразуем строку времени в секунды
  var timer = player.GetVar("Time_3");
  window.timerSeconds = convertTimeStringToSeconds(timer);

  if (!window.timerRunning) {
    window.timerRunning = true;
    window.lastUpdateTime = performance.now();

    // Запускаем интервал для обновления таймера каждую секунду
    window.timerInterval = setInterval(function() {
      // Проверяем значение переменной Timer_Run
      var timerRun = player.GetVar("Timer_Run");

      // Если Timer_Run равен false или "False", останавливаем таймер
      if (timerRun === false || timerRun === "False") {
        stopTimer();
        return;
      }

      // Вычисляем прошедшее время
      var currentTime = performance.now();
      var elapsedTime = Math.round((currentTime - window.lastUpdateTime) / 1000); // в секундах, округлено до ближайшего целого
      window.lastUpdateTime = currentTime;

      // Уменьшаем таймер на прошедшее время
      window.timerSeconds -= elapsedTime;

      // Преобразуем секунды обратно в формат ММ:СС
      var formattedTimer = convertSecondsToTimeString(window.timerSeconds);

      // Обновляем значение переменной Time_3
      player.SetVar("Time_3", formattedTimer);

      // Проверяем, не истекло ли время
      if (window.timerSeconds <= 0) {
        // Устанавливаем значение таймера на 00:00
        player.SetVar("Time_3", "00:00");

        // Останавливаем интервал
        stopTimer();

        // Выполняем действия после окончания таймера (например, переходим на следующий слайд)
        player.SetVar("NextSlide", true);
      }
    }, 1000);
  }
}

// Функция для остановки таймера
function stopTimer() {
  if (window.timerRunning) {
    clearInterval(window.timerInterval);
    window.timerRunning = false;
  }
}

// Функция для преобразования строки времени в секунды
function convertTimeStringToSeconds(timeString) {
  var parts = timeString.split(':');
  var minutes = parseInt(parts[0], 10);
  var seconds = parseInt(parts[1], 10);
  return minutes * 60 + seconds;
}

// Функция для преобразования секунд в строку времени
function convertSecondsToTimeString(seconds) {
  var minutes = Math.floor(seconds / 60);
  var remainingSeconds = seconds % 60;
  return minutes.toString().padStart(2, '0') + ':' + remainingSeconds.toString().padStart(2, '0');
}

// Пример вызова функции при загрузке слайда
startTimer();

// Получить значение переменной test_task_4_store из курса
var player = GetPlayer();
var testTask4Store = player.GetVar("test_task_4_store");

// Проверить, содержит ли строка нули
var containsZeros = testTask4Store.includes('0');

// Установить значение переменной Disable_button_trigger в зависимости от наличия нулей
player.SetVar("Disable_button_trigger", containsZeros);

